/**
 * Sub-issue tree rules: where an issue may sit and how far its subtree reaches.
 *
 * `IssueTree` answers structural questions over the issues of one project,
 * loaded in a single read. `assertPlacement` is the only refusal. Services
 * decide what happens around it; nothing here touches the database.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import type { IssueId } from "@/types/common";

export type IssueHierarchyReason = "cycle" | "too_deep";

/**
 * A placement the tree rules refuse. For a refused creation `issueId` is the
 * parent the new issue was to sit under, since the new issue has no id yet.
 */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: IssueHierarchyReason,
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot sit under itself or anything below it`
        : `Issue ${issueId} would sit deeper than ${MAX_SUB_ISSUE_DEPTH} levels`,
    );
    this.name = "IssueHierarchyError";
  }
}

/** The only fields the tree needs from an issue. */
export interface TreeNode {
  readonly id: IssueId;
  readonly parentId: IssueId | null;
}

/**
 * Parent/child index over a set of issues. Every walk stops at a repeated id,
 * so a loop in stored data degrades to a finite answer instead of hanging.
 */
export class IssueTree<T extends TreeNode> {
  private readonly nodes = new Map<string, T>();
  private readonly children = new Map<string, T[]>();

  constructor(nodes: readonly T[]) {
    for (const node of nodes) {
      this.nodes.set(node.id, node);
    }
    for (const node of nodes) {
      if (node.parentId === null) continue;
      const siblings = this.children.get(node.parentId) ?? [];
      siblings.push(node);
      this.children.set(node.parentId, siblings);
    }
  }

  get(issueId: string): T | undefined {
    return this.nodes.get(issueId);
  }

  /** Ids above `issueId`, nearest first. Empty for a root or an unknown id. */
  ancestorsOf(issueId: string): readonly string[] {
    const chain: string[] = [];
    const seen = new Set<string>([issueId]);
    let parentId = this.nodes.get(issueId)?.parentId ?? null;
    while (parentId !== null && !seen.has(parentId)) {
      chain.push(parentId);
      seen.add(parentId);
      parentId = this.nodes.get(parentId)?.parentId ?? null;
    }
    return chain;
  }

  /** Level of `issueId` in its tree: the number of issues above it. */
  levelOf(issueId: string): number {
    return this.ancestorsOf(issueId).length;
  }

  /** Every issue below `issueId` at any depth, in no particular order. */
  descendantsOf(issueId: string): readonly T[] {
    return this.levelsBelow(issueId).flat();
  }

  /** How many levels sit below `issueId`; 0 when it has no sub-issues. */
  heightOf(issueId: string): number {
    return this.levelsBelow(issueId).length;
  }

  private levelsBelow(issueId: string): T[][] {
    const levels: T[][] = [];
    const seen = new Set<string>([issueId]);
    let frontier: readonly string[] = [issueId];

    while (frontier.length > 0) {
      const level: T[] = [];
      for (const parentId of frontier) {
        for (const child of this.children.get(parentId) ?? []) {
          if (seen.has(child.id)) continue;
          seen.add(child.id);
          level.push(child);
        }
      }
      if (level.length === 0) break;
      levels.push(level);
      frontier = level.map((node) => node.id);
    }

    return levels;
  }
}

/**
 * Refuses a placement that would loop or push any issue past
 * `MAX_SUB_ISSUE_DEPTH`. `issueId` is the issue being placed, or `null` for a
 * brand-new issue, which has no sub-issues yet and cannot close a loop.
 * A root placement (`parentId` null) always fits.
 *
 * The depth test is on the deepest descendant: the sub-issues below the moved
 * issue travel with it, so they land at `level(parent) + 1 + height(issue)`.
 */
export function assertPlacement<T extends TreeNode>(
  tree: IssueTree<T>,
  issueId: IssueId | null,
  parentId: IssueId | null,
): void {
  if (parentId === null) return;

  if (
    issueId !== null &&
    (parentId === issueId || tree.ancestorsOf(parentId).includes(issueId))
  ) {
    throw new IssueHierarchyError(issueId, "cycle");
  }

  const subtreeHeight = issueId === null ? 0 : tree.heightOf(issueId);
  if (tree.levelOf(parentId) + 1 + subtreeHeight > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId ?? parentId, "too_deep");
  }
}

