/** Every issue of one project, archived ones included, for sub-issue tree work. */
export async function listProjectLinks(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueLink[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .all();

  return rows.map((row) => toIssue(row));
}

/** Live direct sub-issues of `parentId`, oldest first: creation time, then number. */
export async function listSubIssues(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );

  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/** Writes the parent link and returns the issue as stored. `null` makes it a root. */
export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/** Rows per UPDATE when archiving a subtree, so no statement binds an oversized id list. */
const ARCHIVE_BATCH_SIZE: number = 500;

/**
 * Archives the listed issues that are still live and returns the ids it
 * archived. Rows already archived keep their original `archived_at`.
 */
export async function archiveIssuesById(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly IssueId[]> {
  const patch = archivePatch();
  const archived: IssueId[] = [];

  for (let start = 0; start < issueIds.length; start += ARCHIVE_BATCH_SIZE) {
    const batch = issueIds.slice(start, start + ARCHIVE_BATCH_SIZE);
    const rows = getDb()
      .update(issues)
      .set(patch)
      .where(
        and(
          ...compact(
            orgPredicate(issues.orgId, orgId),
            inArray(issues.id, [...batch]),
            livePredicate(issues.archivedAt, {}),
          ),
        ),
      )
      .returning({ id: issues.id })
      .all();
    archived.push(...rows.map((row) => row.id as IssueId));
  }

  return archived;
}

