/**
 * Archives the issue and every live issue below it, at any depth. Each issue
 * taken down gets its own `issue.archived`, so the counters, the search index
 * and alerts treat the subtree like any other archive. The parent is never
 * touched; if the archived issue was open, its parent's assignee may be told
 * that nothing open is left below the parent.
 */
export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const tree = await loadProjectTree(orgId, issue.projectId);
  const below = tree
    .descendantsOf(issue.id)
    .filter(isLive)
    .map((node) => node.id);
  const taken = [issue.id, ...below];
  const archivedIds = new Set(await issueRepo.archiveIssuesById(orgId, taken));

  for (const id of taken) {
    if (!archivedIds.has(id)) continue;
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: id,
      projectId: issue.projectId,
    });
  }

  if (!isClosed(issue.status)) {
    await announceIfSubIssuesFinished(
      actor,
      orgId,
      issue.projectId,
      issue.parentId,
    );
  }

  return requireFound(
    await issueRepo.findIssueById(orgId, issue.id),
    "Issue",
    issue.id,
  );
}

/**
 * Places an issue under a parent of the same project, moves it under another
 * parent, or makes it a root again (`parentId: null`). The sub-issues below it
 * travel with it, so the depth check looks at where its deepest descendant
 * would land. A successful change is announced as `issue.updated`.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const tree = await loadProjectTree(input.orgId, before.projectId);
  if (input.parentId !== null) {
    requireLiveParent(tree, input.parentId);
  }
  assertPlacement(tree, before.id, input.parentId);

  if (input.parentId === before.parentId) return before;

  const after = await issueRepo.setIssueParent(
    input.orgId,
    before.id,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** The live direct sub-issues of an issue, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listSubIssues(orgId, issue.id);
}

/** Counts every live issue below an issue, at any depth. Closed means done or canceled. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const tree = await loadProjectTree(orgId, issue.projectId);
  const below = tree.descendantsOf(issue.id).filter(isLive);
  const closed = below.filter((node) => isClosed(node.status)).length;

  return { total: below.length, open: below.length - closed, closed };
}

