function isClosed(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

/** Live and not closed: the only sub-issues that keep a parent from completing. */
function isOpen(node: IssueLink): boolean {
  return isLive(node) && !isClosed(node.status);
}

/** Every issue of one project, for the tree rules. One read per operation. */
async function loadProjectTree(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<IssueTree<IssueLink>> {
  return new IssueTree(await issueRepo.listProjectLinks(orgId, projectId));
}

/** A parent must be a live issue of the same project as the tree; anything else is refused. */
function requireLiveParent(
  tree: IssueTree<IssueLink>,
  parentId: IssueId,
): IssueLink {
  const parent = requireFound(tree.get(parentId), "Issue", parentId);
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/**
 * Tells the direct parent's assignee, once, that nothing open is left below
 * the parent. Silent when there is no parent, the parent is archived or
 * unassigned, or anything below it (at any depth) is still open.
 */
async function announceIfSubIssuesFinished(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId === null) return;

  const tree = await loadProjectTree(orgId, projectId);
  const parent = tree.get(parentId);
  if (parent === undefined || !isLive(parent) || parent.assigneeId === null) {
    return;
  }
  if (tree.descendantsOf(parent.id).some(isOpen)) return;

  await emit("issue.sub_issues_completed", {
    ...actorEnvelope(actor),
    issueId: parent.id,
    projectId,
    assigneeId: parent.assigneeId,
  });
}

