/**
 * Sub-issues: placement rules, listing, roll-up, the archive cascade and the
 * completion notice sent to a parent's assignee.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectService from "@/server/services/project-service";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue, IssueStatus } from "@/types/issue";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

/** Creates an issue in the tenant's project, under `parent` when given. */
async function create(
  tenant: Tenant,
  title: string,
  options: { parent?: Issue; assigneeId?: Tenant["userIds"]["admin"] | null; status?: IssueStatus } = {},
): Promise<Issue> {
  const issue = await issueService.createIssue(tenant.actors.member, {
    ...issueInput(tenant.org.id, tenant.project.id, {
      title,
      assigneeId: options.assigneeId ?? null,
    }),
    parentId: options.parent?.id ?? null,
    status: options.status ?? "backlog",
  });
  return issue;
}

async function setStatus(tenant: Tenant, issue: Issue, status: IssueStatus, actor = tenant.actors.member): Promise<void> {
  await issueService.changeIssueStatus(actor, {
    orgId: tenant.org.id,
    issueId: issue.id,
    status,
  });
}

async function sub(tenant: Tenant, issue: Issue, parent: Issue | null): Promise<Issue> {
  return issueService.setIssueParent(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    parentId: parent?.id ?? null,
  });
}

async function notificationsFor(tenant: Tenant, recipientId: Tenant["userIds"]["admin"]) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

