    expect(error).toBeInstanceOf(IssueHierarchyError);
    expect((error as IssueHierarchyError).reason).toBe("cycle");

    await expect(sub(tenant, top, top)).rejects.toMatchObject({ reason: "cycle" });
    const stored = await issueRepo.findIssueById(tenant.org.id, top.id);
