/**
 * Sub-issues: placement rules, listing, roll-up, the archive cascade and the
 * completion notice sent to a parent's assignee.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectService from "@/server/services/project-service";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Issue, IssueStatus } from "@/types/issue";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

/** Creates an issue in the tenant's project, under `parent` when given. */
async function create(
  tenant: Tenant,
  title: string,
  options: { parent?: Issue; assigneeId?: Tenant["userIds"]["admin"] | null; status?: IssueStatus } = {},
): Promise<Issue> {
  const issue = await issueService.createIssue(tenant.actors.member, {
    ...issueInput(tenant.org.id, tenant.project.id, {
      title,
      assigneeId: options.assigneeId ?? null,
    }),
    parentId: options.parent?.id ?? null,
    status: options.status ?? "backlog",
  });
  return issue;
}

async function setStatus(tenant: Tenant, issue: Issue, status: IssueStatus, actor = tenant.actors.member): Promise<void> {
  await issueService.changeIssueStatus(actor, {
    orgId: tenant.org.id,
    issueId: issue.id,
    status,
  });
}

async function sub(tenant: Tenant, issue: Issue, parent: Issue | null): Promise<Issue> {
  return issueService.setIssueParent(tenant.actors.member, {
    orgId: tenant.org.id,
    issueId: issue.id,
    parentId: parent?.id ?? null,
  });
}

async function notificationsFor(tenant: Tenant, recipientId: Tenant["userIds"]["admin"]) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

describe("services/issue-service — placing issues under parents", () => {
  it("places an issue under a parent of its project and announces parentId", async () => {
    const tenant = await createTenant("hier-place");
    const parent = await create(tenant, "Parent issue");
    const child = await create(tenant, "Child issue");

    const updated = capture("issue.updated");
    const moved = await sub(tenant, child, parent);

    expect(moved.parentId).toBe(parent.id);
    expect(updated).toHaveLength(1);
    expect(updated[0]).toMatchObject({ issueId: child.id, changedFields: ["parentId"] });
  });

  it("makes a root issue again when the parent is removed", async () => {
    const tenant = await createTenant("hier-root");
    const parent = await create(tenant, "Root parent");
    const child = await create(tenant, "Detached child", { parent });

    const updated = capture("issue.updated");
    const detached = await sub(tenant, child, null);

    expect(detached.parentId).toBeNull();
    expect(updated).toHaveLength(1);
    expect(updated[0]?.changedFields).toEqual(["parentId"]);
  });

  it("moves the whole subtree and refuses a move that would push its deepest issue past level 3", async () => {
    const tenant = await createTenant("hier-depth");
    const level0 = await create(tenant, "Level zero");
    const level1 = await create(tenant, "Level one", { parent: level0 });
    const level2 = await create(tenant, "Level two", { parent: level1 });
    await create(tenant, "Level three", { parent: level2 });

    const mover = await create(tenant, "Mover");
    const moverChild = await create(tenant, "Mover child", { parent: mover });

    // Under level two the mover would sit at level 3 and its child at level 4.
    await expect(sub(tenant, mover, level2)).rejects.toMatchObject({
      code: "conflict",
      reason: "too_deep",
    });
    const stored = await issueRepo.findIssueById(tenant.org.id, mover.id);
    expect(stored?.parentId).toBeNull();

    // Under level one the subtree lands on levels 2 and 3, which is allowed.
    const placed = await sub(tenant, mover, level1);
    expect(placed.parentId).toBe(level1.id);
    const below = await issueService.listSubIssues(
      tenant.actors.member,
      tenant.org.id,
      mover.id,
    );
    expect(below.map((issue) => issue.id)).toEqual([]);
    expect(moverChild.parentId).toBe(mover.id);
  });

  it("refuses a cycle, including an issue placed under itself", async () => {
    const tenant = await createTenant("hier-cycle");
    const top = await create(tenant, "Top");
    const middle = await create(tenant, "Middle", { parent: top });
    const bottom = await create(tenant, "Bottom", { parent: middle });

    const error: unknown = await sub(tenant, top, bottom).catch((caught: unknown) => caught);
    expect(error).toBeInstanceOf(IssueHierarchyError);
    expect((error as IssueHierarchyError).reason).toBe("cycle");

    await expect(sub(tenant, top, top)).rejects.toMatchObject({ reason: "cycle" });
    const stored = await issueRepo.findIssueById(tenant.org.id, top.id);
    expect(stored?.parentId).toBeNull();
  });

  it("treats a parent of another project or another workspace as not found", async () => {
    const tenant = await createTenant("hier-scope");
    const other = await createTenant("hier-other");
    const child = await create(tenant, "Scoped child");
    const foreign = await create(other, "Foreign parent");

    const elsewhere = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Elsewhere",
      slug: "elsewhere",
      key: "ELS",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const elsewhereIssue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, elsewhere.id, { title: "Other project" }),
    );

    await expect(sub(tenant, child, elsewhereIssue)).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.setIssueParent(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an archived parent and an archived issue being moved", async () => {
    const tenant = await createTenant("hier-archived");
    const parent = await create(tenant, "Archived parent");
    const child = await create(tenant, "Late child");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);

    await expect(sub(tenant, child, parent)).rejects.toBeInstanceOf(AlreadyArchivedError);

    const archivedChild = await create(tenant, "Archived child");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archivedChild.id);
    await expect(sub(tenant, archivedChild, null)).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("requires issue:update on the issue being placed", async () => {
    const tenant = await createTenant("hier-perm");
    const parent = await create(tenant, "Guarded parent");
    const child = await create(tenant, "Guarded child");

    await expect(
      issueService.setIssueParent(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: child.id,
        parentId: parent.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses another workspace's orgId on every operation with TenantScopeError", async () => {
    const north = await createTenant("hier-north");
    const acme = await createTenant("hier-acme");
    const northIssue = await create(north, "North issue");

    await expect(
      issueService.setIssueParent(acme.actors.owner, {
        orgId: north.org.id,
        issueId: northIssue.id,
        parentId: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.listSubIssues(acme.actors.owner, north.org.id, northIssue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.getIssueRollup(acme.actors.owner, north.org.id, northIssue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("services/issue-service — creating under a parent", () => {
  it("creates a sub-issue under a parent of its project", async () => {
    const tenant = await createTenant("hier-create");
    const parent = await create(tenant, "Create parent");
    const child = await create(tenant, "Create child", { parent });

    expect(child.parentId).toBe(parent.id);
  });

  it("refuses a creation that would sit past level 3 and creates nothing", async () => {
    const tenant = await createTenant("hier-create-deep");
    const level0 = await create(tenant, "Deep zero");
    const level1 = await create(tenant, "Deep one", { parent: level0 });
    const level2 = await create(tenant, "Deep two", { parent: level1 });
    const level3 = await create(tenant, "Deep three", { parent: level2 });

    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id, {
      includeArchived: true,
    });
    const created = capture("issue.created");

    await expect(create(tenant, "Level four", { parent: level3 })).rejects.toMatchObject({
      code: "conflict",
      reason: "too_deep",
    });

    expect(created).toHaveLength(0);
    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id, { includeArchived: true }),
    ).resolves.toBe(before);
  });

  it("refuses a parent of another project and creates nothing", async () => {
    const tenant = await createTenant("hier-create-scope");
    const elsewhere = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Create elsewhere",
      slug: "create-elsewhere",
      key: "CEL",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const foreignParent = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, elsewhere.id, { title: "Foreign parent" }),
    );

    const created = capture("issue.created");
    await expect(create(tenant, "Orphan", { parent: foreignParent })).rejects.toBeInstanceOf(
      NotFoundError,
    );
    expect(created).toHaveLength(0);
  });
});

describe("services/issue-service — listing and roll-up", () => {
  it("lists only live direct sub-issues, oldest first", async () => {
    const tenant = await createTenant("hier-list");
    const parent = await create(tenant, "List parent");
    const first = await create(tenant, "First child", { parent });
    const second = await create(tenant, "Second child", { parent });
    const third = await create(tenant, "Third child", { parent });
    await create(tenant, "Grandchild", { parent: first });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, second.id);

    const listed = await issueService.listSubIssues(
      tenant.actors.member,
      tenant.org.id,
      parent.id,
    );

    expect(listed.map((issue) => issue.id)).toEqual([first.id, third.id]);
  });

  it("rolls up every live issue below at any depth, closed meaning done or canceled", async () => {
    const tenant = await createTenant("hier-rollup");
    const root = await create(tenant, "Rollup root");
    const doneChild = await create(tenant, "Done child", { parent: root });
    const openChild = await create(tenant, "Open child", { parent: root });
    const canceledGrand = await create(tenant, "Canceled grandchild", { parent: doneChild });
    const progressGrand = await create(tenant, "Progress grandchild", { parent: openChild });

    await setStatus(tenant, doneChild, "done");
    await setStatus(tenant, canceledGrand, "canceled");
    await setStatus(tenant, openChild, "todo");
    await setStatus(tenant, progressGrand, "in_progress");

    await expect(
      issueService.getIssueRollup(tenant.actors.member, tenant.org.id, root.id),
    ).resolves.toEqual({ total: 4, open: 2, closed: 2 });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, progressGrand.id);

    await expect(
      issueService.getIssueRollup(tenant.actors.member, tenant.org.id, root.id),
    ).resolves.toEqual({ total: 3, open: 1, closed: 2 });
  });
});

describe("services/issue-service — archiving the subtree", () => {
  it("archives every live issue below, announcing each once, and leaves the parent alone", async () => {
    const tenant = await createTenant("hier-cascade");
    const parent = await create(tenant, "Cascade parent");
    const branch = await create(tenant, "Cascade branch", { parent });
    const leaf = await create(tenant, "Cascade leaf", { parent: branch });
    const earlier = await create(tenant, "Archived earlier", { parent: branch });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, earlier.id);
    const earlierStamp = (await issueRepo.findIssueById(tenant.org.id, earlier.id))?.archivedAt;

    const archived = capture("issue.archived");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, branch.id);

    expect(archived.map((event) => event.issueId).sort()).toEqual(
      [branch.id, leaf.id].sort(),
    );

    const storedLeaf = await issueRepo.findIssueById(tenant.org.id, leaf.id);
    expect(storedLeaf?.archivedAt).not.toBeNull();

    const storedEarlier = await issueRepo.findIssueById(tenant.org.id, earlier.id);
    expect(storedEarlier?.archivedAt).toBe(earlierStamp);

    const storedParent = await issueRepo.findIssueById(tenant.org.id, parent.id);
    expect(storedParent?.archivedAt).toBeNull();
  });
});

describe("services/issue-service — completion notice", () => {
  it("tells the parent's assignee once when the last open sub-issue closes", async () => {
    const tenant = await createTenant("hier-notice");
    const parent = await create(tenant, "Notice parent", { assigneeId: tenant.userIds.admin });
    const first = await create(tenant, "Notice first", { parent });
    const second = await create(tenant, "Notice second", { parent });

    await setStatus(tenant, first, "done");
    expect(await notificationsFor(tenant, tenant.userIds.admin)).toHaveLength(0);

    await setStatus(tenant, second, "canceled");
    const notices = await notificationsFor(tenant, tenant.userIds.admin);
    expect(notices).toHaveLength(1);
    expect(notices[0]).toMatchObject({ kind: "sub_issues_completed", href: `/issues/${parent.id}` });

    // Reopening and closing again tells the assignee again.
    await setStatus(tenant, second, "todo");
    await setStatus(tenant, second, "done");
    expect(await notificationsFor(tenant, tenant.userIds.admin)).toHaveLength(2);
  });

  it("stays silent for moves, reopenings and closed-to-closed changes", async () => {
    const tenant = await createTenant("hier-quiet");
    const parent = await create(tenant, "Quiet parent", { assigneeId: tenant.userIds.admin });
    const child = await create(tenant, "Quiet child", { parent, status: "done" });
    const other = await create(tenant, "Quiet other", { parent, status: "todo" });

    await setStatus(tenant, other, "done");
    expect(await notificationsFor(tenant, tenant.userIds.admin)).toHaveLength(1);

    await setStatus(tenant, child, "canceled");
    await sub(tenant, child, null);
    expect(await notificationsFor(tenant, tenant.userIds.admin)).toHaveLength(1);
  });

  it("fires when an open sub-issue is archived and nothing open remains", async () => {
    const tenant = await createTenant("hier-archive-notice");
    const parent = await create(tenant, "Archive parent", { assigneeId: tenant.userIds.admin });
    const finished = await create(tenant, "Finished", { parent, status: "done" });
    const open = await create(tenant, "Still open", { parent });
    void finished;

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, open.id);
    expect(await notificationsFor(tenant, tenant.userIds.admin)).toHaveLength(1);
  });

  it("never tells the actor about their own change, and considers only the direct parent", async () => {
    const tenant = await createTenant("hier-self");
    const grand = await create(tenant, "Grand parent", { assigneeId: tenant.userIds.admin });
    const parent = await create(tenant, "Middle parent", { parent: grand, assigneeId: tenant.userIds.member });
    const child = await create(tenant, "Only child", { parent });

    await setStatus(tenant, child, "done");

    expect(await notificationsFor(tenant, tenant.userIds.member)).toHaveLength(0);
    expect(await notificationsFor(tenant, tenant.userIds.admin)).toHaveLength(0);
  });
});

