it("considers only the direct parent", async () => {
  const tenant = await createTenant("hier-direct");
  const grand = await create(tenant, "Grand parent", { assigneeId: tenant.userIds.owner });
  const parent = await create(tenant, "Middle parent", { parent: grand, assigneeId: tenant.userIds.admin });
  const child = await create(tenant, "Only child", { parent });

  await setStatus(tenant, child, "done");

  expect(await notificationsFor(tenant, tenant.userIds.admin)).toHaveLength(1);
  expect(await notificationsFor(tenant, tenant.userIds.owner)).toHaveLength(0);
});

it("never tells the actor about their own change", async () => {
  const tenant = await createTenant("hier-self");
  const parent = await create(tenant, "Self parent", { assigneeId: tenant.userIds.member });
  const child = await create(tenant, "Self child", { parent });

  await setStatus(tenant, child, "done");

  expect(await notificationsFor(tenant, tenant.userIds.member)).toHaveLength(0);
});

